import type { BaseQueryFn } from '@reduxjs/toolkit/query';
import { initialAxios } from 'Api/Api';
import type { AxiosError } from 'axios';
import FilterDataAccessor from 'domain/Filter/FilterDataAccessor/FilterDataAccessor';
import { getViewtype, normalizeFilters } from 'utils/filter/filter';

import type { RootState } from '../../store/configureStore';

export interface BffQueryArgs {
  endpoint: string;
  dt_end?: string;
  subFilters?: Record<string, unknown>;
  skipMainFilters?: boolean;
  method?: 'GET' | 'POST';
  body?: unknown;
}

const DEFAULT_BFF_URL = '/api/martech-oneway-reports-bff/v1';

const getBffUrl = (): string =>
  localStorage.getItem('bffUrl') || DEFAULT_BFF_URL;

const wrapParams = (
  params: Record<string, unknown>,
): Record<string, unknown> => {
  return Object.entries(params).reduce(
    (acc: Record<string, unknown>, [key, value]) => {
      acc[`filter[${key}]`] = value;
      return acc;
    },
    {},
  );
};

export const bffBaseQuery: BaseQueryFn<
  BffQueryArgs,
  unknown,
  { status?: number; data?: unknown }
> = async (args, api) => {
  const { endpoint, dt_end, subFilters, skipMainFilters, method, body } = args;
  const state = api.getState() as RootState;

  const currentPage = state.filters.currentPage;
  const page = currentPage ? state.filters.pages[currentPage] : null;
  const applied = page?.applied;
  const dataFilters = page?.dataFilters;

  const activeFilters =
    !skipMainFilters && applied ? normalizeFilters(applied) : null;

  const viewtype = activeFilters?.country
    ? getViewtype(activeFilters.country)
    : undefined;

  const dt_ini = dataFilters
    ? FilterDataAccessor.getInstance().getTimeFrame(dataFilters, 'ini')
    : null;

  const requestParams = {
    viewtype,
    dt_ini,
    dt_end,
    ...activeFilters,
    ...subFilters,
  };

  const apiPrefix = getBffUrl();
  const url = `${apiPrefix}${endpoint}`;

  try {
    const params = wrapParams(requestParams);
    const result =
      method === 'POST'
        ? await initialAxios.post(url, body, { params })
        : await initialAxios.get(url, { params });
    return { data: result.data };
  } catch (err) {
    const axiosError = err as AxiosError;
    return {
      error: {
        status: axiosError.response?.status,
        data: axiosError.response?.data ?? axiosError.message,
      },
    };
  }
};
